#include <unordered_map>
#include <cmath>
#include <climits>

class RideSharingSystem {
    std::unordered_map<int, std::pair<int, int>> drivers;
    std::unordered_map<int, int> activeRides;
public:
    RideSharingSystem() {}

    void addDriver(int driverId, int x, int y) {
        drivers[driverId] = {x, y};
    }

    int requestRide(int riderId, int x, int y) {
        if (drivers.empty()) return -1;
        int bestDist = INT_MAX;
        int bestId = -1;
        for (const auto& [dId, pos] : drivers) {
            int d = std::abs(pos.first - x) + std::abs(pos.second - y);
            if (d < bestDist || (d == bestDist && (bestId == -1 || dId < bestId))) {
                bestDist = d;
                bestId = dId;
            }
        }
        if (bestId != -1) {
            drivers.erase(bestId);
            activeRides[riderId] = bestId;
        }
        return bestId;
    }

    void completeRide(int riderId, int x, int y) {
        if (activeRides.count(riderId)) {
            int dId = activeRides[riderId];
            activeRides.erase(riderId);
            drivers[dId] = {x, y};
        }
    }
};

import java.util.*;

class RideSharingSystem {
    private Map<Integer, int[]> drivers = new HashMap<>();
    private Map<Integer, Integer> activeRides = new HashMap<>();

    public RideSharingSystem() {}

    public void addDriver(int driverId, int x, int y) {
        drivers.put(driverId, new int[]{x, y});
    }

    public int requestRide(int riderId, int x, int y) {
        if (drivers.isEmpty()) return -1;
        int bestDist = Integer.MAX_VALUE;
        int bestId = -1;
        for (var entry : drivers.entrySet()) {
            int dId = entry.getKey();
            int[] pos = entry.getValue();
            int d = Math.abs(pos[0] - x) + Math.abs(pos[1] - y);
            if (d < bestDist || (d == bestDist && (bestId == -1 || dId < bestId))) {
                bestDist = d;
                bestId = dId;
            }
        }
        if (bestId != -1) {
            drivers.remove(bestId);
            activeRides.put(riderId, bestId);
        }
        return bestId;
    }

    public void completeRide(int riderId, int x, int y) {
        if (activeRides.containsKey(riderId)) {
            int dId = activeRides.remove(riderId);
            drivers.put(dId, new int[]{x, y});
        }
    }
}

class RideSharingSystem {
    constructor() {
        this.drivers = new Map();
        this.activeRides = new Map();
    }

    addDriver(driverId, x, y) {
        this.drivers.set(driverId, [x, y]);
    }

    requestRide(riderId, x, y) {
        if (this.drivers.size === 0) return -1;
        let bestDist = Infinity;
        let bestId = -1;
        for (const [dId, pos] of this.drivers.entries()) {
            const d = Math.abs(pos[0] - x) + Math.abs(pos[1] - y);
            if (d < bestDist || (d === bestDist && (bestId === -1 || dId < bestId))) {
                bestDist = d;
                bestId = dId;
            }
        }
        if (bestId !== -1) {
            this.drivers.delete(bestId);
            this.activeRides.set(riderId, bestId);
        }
        return bestId;
    }

    completeRide(riderId, x, y) {
        if (this.activeRides.has(riderId)) {
            const dId = this.activeRides.get(riderId);
            this.activeRides.delete(riderId);
            this.drivers.set(dId, [x, y]);
        }
    }
}
